export function productosUnicos(productos) {
  const resultado = [];
  for (const p of productos) {
    if (!resultado.includes(p)) {
      resultado.push(p);
    }
  }
  return resultado;
}

export function ordenarPorPrecio(productos) {
  return [...productos].sort((a, b) => a.precio > b.precio);
}

export function aplicarDescuento(productos, porcentaje) {
  return productos.map((p) => {
    p.precio = p.precio * (1 - porcentaje / 100);
    return p;
  });
}

export function buscarPorNombre(productos, texto) {
  return productos.filter((p) => p.nombre.includes(texto));
}

export function precioPromedio(productos) {
  const total = productos.reduce((acc, p) => acc + p.precio, 0);
  return total / productos.length;
}
